-- Contenus pédagogiques fictifs pour remplir le Front Office.
-- Importer APRES database_actualites.sql ; import réexécutable sans doublons de titre.
USE civlink_auth;
INSERT INTO actualite (idCategorie, titre, resume, contenu, icone, lecture, lien, lienTexte, statut, datePublication) SELECT c.idCategorie, 'Préparer ses documents avant une démarche','Conseils pour organiser ses pièces avant de se déplacer.','Cette actualité est un conseil de démonstration CIVLINK, et non une annonce officielle.

Consultez la rubrique Démarches pour identifier les justificatifs qui peuvent être demandés. Vérifiez ensuite les conditions exactes auprès du service public compétent.','fas fa-folder-open','3 min','demarches.php','Explorer les démarches', 'publie', NOW() FROM categorie_actualite c WHERE c.nom='Démarches' AND NOT EXISTS (SELECT 1 FROM actualite a WHERE a.titre='Préparer ses documents avant une démarche') LIMIT 1;
INSERT INTO actualite (idCategorie, titre, resume, contenu, icone, lecture, lien, lienTexte, statut, datePublication) SELECT c.idCategorie, 'Trouver une administration sur la carte CIVLINK','Utiliser les filtres et la carte interactive pour chercher un service.','Cette actualité présente le fonctionnement du prototype CIVLINK.

Dans Administrations, recherchez un nom ou une catégorie, saisissez une adresse puis utilisez le rayon de recherche pour localiser les établissements. Vérifiez leurs coordonnées avant un déplacement réel.','fas fa-map-marked-alt','2 min','administrations.php','Voir les administrations', 'publie', NOW() FROM categorie_actualite c WHERE c.nom='Services publics' AND NOT EXISTS (SELECT 1 FROM actualite a WHERE a.titre='Trouver une administration sur la carte CIVLINK') LIMIT 1;
INSERT INTO actualite (idCategorie, titre, resume, contenu, icone, lecture, lien, lienTexte, statut, datePublication) SELECT c.idCategorie, 'Comment rédiger un signalement utile','Décrivez précisément un problème de voirie, de déchets ou d’éclairage.','Cet article est un guide pédagogique CIVLINK.

Indiquez une adresse, décrivez le problème et joignez éventuellement une photo sans exposer les données personnelles d’autres personnes. Le prototype enregistre vos signalements mais ne les transmet pas aux municipalités.','fas fa-bullhorn','2 min','signalements.php','Faire un signalement', 'publie', NOW() FROM categorie_actualite c WHERE c.nom='Vie citoyenne' AND NOT EXISTS (SELECT 1 FROM actualite a WHERE a.titre='Comment rédiger un signalement utile') LIMIT 1;
INSERT INTO actualite (idCategorie, titre, resume, contenu, icone, lecture, lien, lienTexte, statut, datePublication) SELECT c.idCategorie, 'Comprendre la simulation de paiement','Découvrez comment tester la gestion de factures STEG et SONEDE.','Cette actualité décrit une fonction de démonstration CIVLINK.

Dans Factures, vous pouvez simuler un règlement et consulter un reçu fictif. Aucun service officiel STEG ou SONEDE n’est connecté, et aucune transaction réelle n’est effectuée.','fas fa-file-invoice','2 min','factures.php','Voir les factures', 'publie', NOW() FROM categorie_actualite c WHERE c.nom='Factures' AND NOT EXISTS (SELECT 1 FROM actualite a WHERE a.titre='Comprendre la simulation de paiement') LIMIT 1;
INSERT INTO actualite (idCategorie, titre, resume, contenu, icone, lecture, lien, lienTexte, statut, datePublication) SELECT c.idCategorie, 'Préparer un rendez-vous administratif','Les réflexes à avoir avant de réserver un créneau.','Article de démonstration CIVLINK.

Identifiez le service concerné, renseignez-vous sur les justificatifs et choisissez un créneau disponible. Les éventuels créneaux affichés par le prototype ne sont pas des réservations officielles.','far fa-calendar-check','2 min','rendezvous.php','Voir les rendez-vous', 'publie', NOW() FROM categorie_actualite c WHERE c.nom='Rendez-vous' AND NOT EXISTS (SELECT 1 FROM actualite a WHERE a.titre='Préparer un rendez-vous administratif') LIMIT 1;
INSERT INTO actualite (idCategorie, titre, resume, contenu, icone, lecture, lien, lienTexte, statut, datePublication) SELECT c.idCategorie, 'Les six gestions du projet CIVLINK','Découvrez les modules principaux du portail citoyen.','Actualité de présentation du projet CIVLINK.

Le prototype regroupe Administrations, Démarches, Signalements, Factures, Rendez-vous et Actualités. Un compte citoyen et un assistant FAQ complètent la navigation.','fas fa-layer-group','2 min','../index.php','Revenir à l’accueil', 'publie', NOW() FROM categorie_actualite c WHERE c.nom='CIVLINK' AND NOT EXISTS (SELECT 1 FROM actualite a WHERE a.titre='Les six gestions du projet CIVLINK') LIMIT 1;
